fn review(owner:&Arc<Owned>,goal:&Record,bus:&Bus)->super::super::recipe_controller::Review{
    owner.review_recipe_with_criteria(goal,&goal.plans[0].id,"wait-review",Arc::new(Target::fixture_at(&bus.address).unwrap()),&generated::config(),&[],crate::assistant_memory::now()).unwrap()
}
fn source(owner:&Arc<Owned>,goal:&Record,review:&super::super::recipe_controller::Review,store:&Arc<Store>)->Source{Source::capture(owner.clone(),goal,review,store.clone(),Arc::new(||Ok(generated::config()))).unwrap()}
#[test]fn same_original_decision_yields_for_manual_work_and_reacquires_before_verified_effects(){
    let(f,a,goal,_pending,owner,main)=generated::setup(true);let owner=Arc::new(owner);let store=Arc::new(generated::native(&f));let bus=Bus::new();let player=Player::new(&bus,"Private resource wait");let review=review(&owner,&goal,&bus);let source=source(&owner,&goal,&review,&store);let lease=owner.lease().clone();let before=grant(&f,&goal)["body"]["budgetUsage"].clone();
    let worker=owner.readiness_worker(crate::assistant_memory::now()).unwrap();assert!(matches!(owner.yield_for_decision(&store,&source,crate::assistant_memory::now()),Err(model::Error::Busy)));assert!(main.runtime_resources().acquire("ollama",Arc::default(),None).is_err());drop(worker);
    owner.yield_for_decision(&store,&source,crate::assistant_memory::now()).unwrap();assert!(!owner.live.hold.occupies_slot());assert!(source.current());assert!(owner.worker(crate::assistant_memory::now()).is_err());assert!(owner.readiness_worker(crate::assistant_memory::now()).is_err());assert_eq!(grant(&f,&goal)["body"]["phase"],"waiting");assert_eq!(grant(&f,&goal)["body"]["budgetUsage"],before);
    let manual=main.runtime_resources().acquire("ollama",Arc::default(),None).unwrap();let independent=main.runtime_resources().acquire("copilot",Arc::default(),None).unwrap();assert!(manual.current()&&independent.current());let pending=crate::cli_chat::goal_decision_fixture(source.clone());pending.panel_answer(true,pending.request["goalTarget"].clone()).unwrap();let decision=pending.decision().unwrap();assert!(matches!(owner.resume_after_decision(&store,&source,crate::assistant_memory::now()),Err(model::Error::Busy)));assert!(player.calls.lock().unwrap().is_empty());assert_eq!(owner.lease(),&lease);
    drop(manual);owner.resume_after_decision(&store,&source,crate::assistant_memory::now()).unwrap();assert!(owner.current(crate::assistant_memory::now()));assert_eq!(owner.live.hold.generation(),2);assert!(independent.current());let(approved,ready)=review.approve_decision(decision,&owner,&goal,&generated::config(),crate::assistant_memory::now()).unwrap();let row=&goal.admissions[0];let scope=a.issue_recipe(&row.spec,row.proof.as_ref().unwrap(),owner.lease(),&approved,crate::assistant_memory::now()).unwrap();ready.activate(&scope).unwrap();let result=owner.run_recipe_for_store(&store,&goal,&ready,||Ok(generated::config()),|_|{}).unwrap();assert!(result.progress.criteria_verified&&result.progress.goal_complete);assert_eq!(player.calls.lock().unwrap().len(),2);let body=grant(&f,&goal)["body"].clone();assert_eq!(body["schemaVersion"],6);assert_eq!(body["resourceUsage"]["entries"].as_array().unwrap().len(),1);assert!(body["resourceUsage"]["entries"][0]["resumedAt"].is_u64());assert_eq!(body["budgetUsage"]["attempts"].as_array().unwrap().len(),3);assert_eq!(owner.lease(),&lease);
}
#[test]fn stop_while_yielded_does_not_cancel_or_release_a_different_owner(){
    let(f,a,goal,_pending,owner,main)=generated::setup(true);let owner=Arc::new(owner);let store=Arc::new(generated::native(&f));let bus=Bus::new();let player=Player::new(&bus,"Private stopped wait");let review=review(&owner,&goal,&bus);let source=source(&owner,&goal,&review,&store);owner.yield_for_decision(&store,&source,crate::assistant_memory::now()).unwrap();let manual=main.runtime_resources().acquire("ollama",Arc::default(),None).unwrap();let pending=crate::cli_chat::goal_decision_fixture(source.clone());
    super::super::signal_stop(owner.lease());assert!(!source.pending());assert!(pending.panel_answer(true,pending.request["goalTarget"].clone()).is_err());assert!(owner.resume_after_decision(&store,&source,crate::assistant_memory::now()).is_err());let drain=owner.drain(DrainOutcome::Confirmed).unwrap();store.drain_owned(&a,&drain,crate::assistant_memory::now()).unwrap();owner.live.hold.release_drained(&drain).unwrap();assert!(manual.current());assert!(main.runtime_resources().acquire("ollama",Arc::default(),None).is_err());assert!(player.calls.lock().unwrap().is_empty());assert_eq!(grant(&f,&goal)["body"]["budgetUsage"]["attempts"].as_array().unwrap().len(),1);
}
#[test]fn uncertain_yield_and_resume_keep_native_state_and_ack_without_new_reservation_or_budget(){
    use std::os::fd::AsRawFd;
    let(f,_a,goal,_pending,owner,main)=generated::setup(true);let owner=Arc::new(owner);let store=Arc::new(generated::native(&f));let bus=Bus::new();let player=Player::new(&bus,"Private uncertain resource wait");let review=review(&owner,&goal,&bus);let source=source(&owner,&goal,&review,&store);let before=grant(&f,&goal)["body"]["budgetUsage"].clone();let lock=std::fs::OpenOptions::new().read(true).write(true).open(root(&f).join(".catalog.lock")).unwrap();assert_eq!(unsafe{libc::flock(lock.as_raw_fd(),libc::LOCK_EX|libc::LOCK_NB)},0);
    assert!(owner.yield_for_decision(&store,&source,crate::assistant_memory::now()).is_err());assert!(owner.live.hold.occupies_slot());drop(lock);
    // The first busy observation precedes proposal capture. Capture the original
    // native proposal under its owner gate, then inject an actual publish fault.
    let entry=source.resource_entry(&owner,crate::assistant_memory::now(),1).unwrap();*owner.live.waiting.lock().unwrap()=Some(Waiting{entry:entry.clone(),stage:Stage::Prepared});let native=YieldProof{live:owner.live.clone(),entry};let row=&goal.admissions[0];let mut authority=Authority::existing(&root(&f)).unwrap();authority.fault=Fault::AfterGrantPublish;assert!(authority.yield_resource(&row.spec,row.proof.as_ref().unwrap(),owner.lease(),&native,crate::assistant_memory::now()).is_err());assert!(owner.live.hold.occupies_slot());assert!(!source.current());assert!(source.pending());assert!(main.runtime_resources().acquire("ollama",Arc::default(),None).is_err());
    owner.yield_for_decision(&store,&source,crate::assistant_memory::now()).unwrap();assert!(!owner.live.hold.occupies_slot());assert!(source.current());owner.live.hold.reacquire_waiting(&native).unwrap();owner.live.waiting.lock().unwrap().as_mut().unwrap().stage=Stage::Acquired;assert!(authority.resume_resource(&row.spec,row.proof.as_ref().unwrap(),owner.lease(),&native,crate::assistant_memory::now()).is_err());assert!(owner.live.hold.occupies_slot());assert!(owner.worker(crate::assistant_memory::now()).is_err());owner.resume_after_decision(&store,&source,crate::assistant_memory::now()).unwrap();assert!(owner.current(crate::assistant_memory::now()));assert_eq!(owner.live.hold.generation(),2);let body=grant(&f,&goal)["body"].clone();assert_eq!(body["resourceUsage"]["entries"].as_array().unwrap().len(),1);assert_eq!(body["budgetUsage"],before);assert!(player.calls.lock().unwrap().is_empty());
}
#[test]fn an_old_yield_proof_cannot_release_the_reacquired_generation_or_a_foreign_hold(){
    let(f,_a,goal,_pending,owner,main)=generated::setup(true);let owner=Arc::new(owner);let store=Arc::new(generated::native(&f));let bus=Bus::new();let _player=Player::new(&bus,"Private old wait proof");let review=review(&owner,&goal,&bus);let source=source(&owner,&goal,&review,&store);owner.yield_for_decision(&store,&source,crate::assistant_memory::now()).unwrap();let entry=owner.live.waiting.lock().unwrap().as_ref().unwrap().entry.clone();let old=YieldProof{live:owner.live.clone(),entry};let foreign=main.runtime_resources().acquire("copilot",Arc::default(),None).unwrap();assert!(foreign.release_waiting(&old).is_err());assert!(foreign.current());owner.resume_after_decision(&store,&source,crate::assistant_memory::now()).unwrap();assert!(owner.live.hold.release_waiting(&old).is_err());assert!(owner.live.hold.current());assert!(main.runtime_resources().acquire("ollama",Arc::default(),None).is_err());
}
#[test]fn a_second_goal_can_claim_the_provider_while_the_original_owner_waits(){
    use crate::pet_runtime::{admission::{Review,Payment},admission_tests::{evidence,budget},planning::Limits};
    let(f,a,goal,_pending,owner,main)=generated::setup(true);let owner=Arc::new(owner);let store=Arc::new(generated::native(&f));let bus=Bus::new();let _player=Player::new(&bus,"Private queued fairness");let review=review(&owner,&goal,&bus);let source=source(&owner,&goal,&review,&store);owner.yield_for_decision(&store,&source,crate::assistant_memory::now()).unwrap();let old_lease=owner.lease().clone();
    let draft=f.goal_named("ollama","second-wait-owner");let at=crate::assistant_memory::now();let mut bounds=budget();bounds.deadline_at=at+60_000;bounds.payment=Payment::LocalOnly;
    let approved=Review::prepare_planning(&draft,evidence(&draft,at),bounds,Limits{max_rounds:3,max_steps:2,max_output_bytes:2048,no_progress_limit:2},&generated::config(),"second-admit".into(),nonce().unwrap(),at).unwrap().approve(&draft,evidence(&draft,at),at).unwrap();let certified=a.certify(&approved,&draft,at).unwrap();let queued=f.store().enqueue_certified(&certified,at).unwrap().record;let controller=Controller::new().unwrap();let pending=controller.prepare(&queued,&root(&f),&f.path.join("contexts"),&main,&evidence(&queued,at),"second-claim".into(),at,Arc::new(|_,_,_|Validity::Current)).unwrap();let(receipt,second)=pending.claim(&f.store(),&a,&evidence(&queued,at),at).unwrap();let second=second.unwrap();assert_ne!(second.lease().id,old_lease.id);assert!(second.current(at));assert!(source.current());assert!(matches!(owner.resume_after_decision(&store,&source,crate::assistant_memory::now()),Err(model::Error::Busy)));
    let drain=second.drain(DrainOutcome::Confirmed).unwrap();f.store().drain_owned(&a,&drain,crate::assistant_memory::now()).unwrap();second.live.hold.release_drained(&drain).unwrap();owner.resume_after_decision(&store,&source,crate::assistant_memory::now()).unwrap();assert_eq!(owner.lease(),&old_lease);assert!(owner.current(crate::assistant_memory::now()));assert_ne!(receipt.record.id,goal.id);
}

struct BusyEnv{address:String,resources:Arc<crate::pet_resources::Coordinator>,manual:Mutex<Option<Arc<crate::pet_resources::Hold>>>,statuses:Mutex<Vec<super::super::dispatcher::Status>>}
#[test]fn yielded_owner_closes_on_pause_cancel_or_expiry_without_reacquiring_or_disturbing_another_native_owner(){
    use crate::pet_runtime::{admission::{Review,Payment},admission_tests::{evidence,budget},planning::Limits,authority_store::mutate_with_authority,model::{Action,State}};
    for stop in [Some(Action::Pause),Some(Action::Cancel),None]{
        let(f,a,goal,_first_pending,owner,main)=generated::setup(true);let owner=Arc::new(owner);let store=Arc::new(generated::native(&f));let bus=Bus::new();let player=Player::new(&bus,"Private other native owner");let proposal=review(&owner,&goal,&bus);let source=source(&owner,&goal,&proposal,&store);owner.yield_for_decision(&store,&source,crate::assistant_memory::now()).unwrap();let before=grant(&f,&goal)["body"].clone();
        let draft=f.goal_named("ollama","independent-owner-during-close");let at=crate::assistant_memory::now();let mut bounds=budget();bounds.deadline_at=at+60_000;bounds.payment=Payment::LocalOnly;
        let approved=Review::prepare_planning(&draft,evidence(&draft,at),bounds,Limits{max_rounds:3,max_steps:2,max_output_bytes:2048,no_progress_limit:2},&generated::config(),"other-admit".into(),nonce().unwrap(),at).unwrap().approve(&draft,evidence(&draft,at),at).unwrap();let certified=a.certify(&approved,&draft,at).unwrap();let queued=f.store().enqueue_certified(&certified,at).unwrap().record;let controller=Controller::new().unwrap();let pending=controller.prepare(&queued,&root(&f),&f.path.join("contexts"),&main,&evidence(&queued,at),"other-claim".into(),at,Arc::new(|_,_,_|Validity::Current)).unwrap();let(_,second)=pending.claim(&f.store(),&a,&evidence(&queued,at),at).unwrap();let second=second.unwrap();let second_before=grant(&f,&queued);let lease=second.lease().clone();assert!(second.current(at));
        let(expired,expected,close_at)=match stop{Some(action)=>{let expected=if matches!(action,Action::Cancel){State::Cancelled}else{State::Paused};let now=crate::assistant_memory::now();mutate_with_authority(&*store,&root(&f),&goal.id,"ai_ollama",&goal.revision,"stop-yielded-native".into(),action,now).unwrap();(false,expected,now)},None=>(true,State::RecoveryRequired,owner.lease().deadline_at+1)};
        let proof=owner.drain(DrainOutcome::Confirmed).unwrap();let ended=store.drain_owned(&a,&proof,close_at).unwrap();assert_eq!(ended.record.state,expected);owner.live.hold.release_drained(&proof).unwrap();assert!(!owner.live.hold.occupies_slot());assert_eq!(owner.live.hold.generation(),1);assert_eq!(second.lease(),&lease);assert!(second.current(crate::assistant_memory::now()));let worker=second.readiness_worker(crate::assistant_memory::now()).unwrap();assert!(worker.in_flight_current(crate::assistant_memory::now()));drop(worker);
        let after=grant(&f,&goal)["body"].clone();assert_eq!(after["budgetUsage"],before["budgetUsage"]);assert_eq!(after["resourceUsage"],before["resourceUsage"]);assert_eq!(grant(&f,&queued),second_before);assert!(player.calls.lock().unwrap().is_empty());assert!(main.runtime_resources().acquire("ollama",Arc::default(),None).is_err());if expired{assert_eq!(after["phase"],"closed");}
    }
}
impl super::super::dispatcher::Environment for BusyEnv{
    fn capture(&self,_:&Owned)->model::Result<super::super::dispatcher::Capture>{panic!("The settled native proposal must not request another model call")}
    fn configuration(&self)->model::Result<crate::pet_config::Configuration>{Ok(generated::config())}
    fn target(&self)->model::Result<Arc<Target>>{Ok(Arc::new(Target::fixture_at(&self.address).unwrap()))}
    fn decide(&self,source:Source)->Option<crate::pet_runtime::recipe_decisions::Decision>{
        let manual=self.resources.acquire("ollama",Arc::default(),None).unwrap();*self.manual.lock().unwrap()=Some(manual);assert!(source.current());let pending=crate::cli_chat::goal_decision_fixture(source);pending.panel_answer(true,pending.request["goalTarget"].clone()).unwrap();pending.decision()
    }
    fn notify(&self,status:&super::super::dispatcher::Status){self.statuses.lock().unwrap().push(status.clone());}
}
#[test]fn native_driver_retains_approved_review_while_busy_then_completes_or_stops_without_touching_other_owner(){
    use super::super::dispatcher::{Driver,Phase};
    for stop in [false,true]{
        let(f,_a,goal,_pending,owner,main)=generated::setup(true);let owner=Arc::new(owner);let store=Arc::new(generated::native(&f));let bus=Bus::new();let player=Player::new(&bus,"Private busy driver");let env=Arc::new(BusyEnv{address:bus.address.clone(),resources:main.runtime_resources(),manual:Mutex::new(None),statuses:Mutex::new(vec![])});let driver=Driver::new(owner.clone(),store.clone(),env.clone()).unwrap();driver.spawn().unwrap();let until=Instant::now()+Duration::from_secs(5);
        while driver.status().unwrap().phase!=Phase::WaitingResource&&Instant::now()<until{std::thread::sleep(Duration::from_millis(5));}
        let waiting=driver.status().unwrap();assert_eq!(waiting.phase,Phase::WaitingResource);assert!(waiting.active&&waiting.retained_approval);assert!(env.manual.lock().unwrap().as_ref().unwrap().current());assert!(player.calls.lock().unwrap().is_empty());assert_eq!(grant(&f,&goal)["body"]["budgetUsage"]["attempts"].as_array().unwrap().len(),1);
        if stop{super::super::signal_stop(owner.lease());}else{env.manual.lock().unwrap().take();}
        while driver.status().unwrap().active&&Instant::now()<until{std::thread::sleep(Duration::from_millis(5));}
        let finished=driver.status().unwrap();assert!(!finished.active);if stop{assert_eq!(finished.phase,Phase::Stopped);assert!(env.manual.lock().unwrap().as_ref().unwrap().current());assert!(player.calls.lock().unwrap().is_empty());}else{assert_eq!(finished.phase,Phase::Completed);assert_eq!(store.read(&goal.id,"ai_ollama").unwrap().state,model::State::Completed);assert_eq!(player.calls.lock().unwrap().len(),2);assert!(main.runtime_resources().acquire("ollama",Arc::default(),None).is_ok());}
    }
}
